\label{def:7.1}
[Measurable sets and Lebesgue measure axioms]
Let $n\in\mathbb{N}$. A collection $\mathcal{M}\subseteq \mathcal{P}(\mathbb{R}^n)$ is called a \emph{$\sigma$-algebra of measurable sets} if it satisfies:
 egin{enumerate}
\item[(i)] (Borel property) Every open set in $\mathbb{R}^n$ belongs to $\mathcal{M}$.
\item[(ii)] (Complementarity) If $\Omega\in\mathcal{M}$, then $\mathbb{R}^n\setminus\Omega\in\mathcal{M}$.
\item[(iv)] ($\sigma$-algebra property) If $(\Omega_j)_{j\in J}$ is a countable family in $\mathcal{M}$, then $ igcup_{j\in J}\Omega_j\in\mathcal{M}$ and $ igcap_{j\in J}\Omega_j\in\mathcal{M}$.
\end{enumerate}
A function $m:\mathcal{M}	o[0,+\infty]$ is called a \emph{Lebesgue measure} on $\mathcal{M}$ if it satisfies:
 egin{enumerate}
\item[(v)] (Empty set) $m(\emptyset)=0$.
\item[(vi)] (Positivity) $0\le m(\Omega)\le +\infty$ for all $\Omega\in\mathcal{M}$.
\item[(xi)] (Countable additivity) If $(A_j)_{j\in J}$ is a countable family of pairwise disjoint sets in $\mathcal{M}$, then
\[
\label{eq:7.u1}

m\left( igcup_{j\in J} A_jight)=\sum_{j\in J} m(A_j).

\]
\item[(xii)] (Normalization) $m([0,1]^n)=1$.
\item[(xiii)] (Translation invariance) If $\Omega\in\mathcal{M}$ and $x\in\mathbb{R}^n$, then $x+\Omega:=\{x+y:y\in\Omega\}\in\mathcal{M}$ and $m(x+\Omega)=m(\Omega)$.
\end{enumerate}
\end{definition}

\begin{definition}
\label{def:7.2}
[Open box and volume]
An \emph{open box} (or \emph{box}) in $\mathbb{R}^n$ is a set of the form
\[
\label{eq:7.u6}
B=\prod_{i=1}^n (a_i,b_i)=\{(x_1,\dots,x_n)\in\mathbb{R}^n : x_i\in(a_i,b_i)\text{ for all } i\in\{1,\dots,n\}\},
\]
where $a_i,b_i\in\mathbb{R}$ satisfy $a_i\le b_i$ for each $i\in\{1,\dots,n\}$. The \emph{volume} of $B$ is defined by
\[
\label{eq:7.u7}
\mathrm{vol}(B):=\prod_{i=1}^n (b_i-a_i).
\]
\end{definition}

\begin{definition}
\label{def:7.3}
[Covering by boxes]
Let $\Omega\subseteq\mathbb{R}^n$. A family $(B_j)_{j\in J}$ of boxes in $\mathbb{R}^n$ is called a \emph{covering} of $\Omega$ (or is said to \emph{cover} $\Omega$) if
\[
\label{eq:7.u8}
\Omega\subseteq\bigcup_{j\in J} B_j.
\]
\end{definition}

\begin{proposition}
\label{prop:7.1}
Let $m$ be the outer measure on $\mathbb{R}^d$ defined by
\[
\label{eq:7.u9}
m(E)=\inf\left\{\sum_{j\in J}\operatorname{vol}(B_j): (B_j)_{j\in J}\text{ covers }E,\ J\text{ at most countable}\right\},
\]
where each $B_j$ is a box and $\operatorname{vol}(B_j)$ denotes its volume. Then for every set $\Omega\subseteq\mathbb{R}^d$ and every at most countable family $(B_j)_{j\in J}$ of boxes that covers $\Omega$,
\[
\label{eq:7.u10}
m(\Omega)\le m\Bigl(\bigcup_{j\in J}B_j\Bigr)\le \sum_{j\in J} m(B_j)=\sum_{j\in J}\operatorname{vol}(B_j).
\]
In particular,
\[
m(\Omega) \le \inf\left\{\sum_{j\in J}\operatorname{vol}(B_j): (B_j)_{j\in J}\text{ covers }\Omega,\ J\text{ at most countable}\right\}.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.1}
Since $\Omega\subseteq\bigcup_{j\in J}B_j$, monotonicity of the outer measure implies
\[
\label{eq:7.u11}
m(\Omega)\le m\Bigl(\bigcup_{j\in J}B_j\Bigr).
\]
For each $j\in J$, the singleton family $(B_j)$ covers $B_j$, hence by the definition of $m$,
\[
\label{eq:7.u12}
m(B_j)\le \operatorname{vol}(B_j).
\]
By countable subadditivity of the outer measure,
\[
\label{eq:7.u13}
m\Bigl(\bigcup_{j\in J}B_j\Bigr)\le \sum_{j\in J} m(B_j)\le \sum_{j\in J}\operatorname{vol}(B_j).
\]
Finally, for a box $B$, any at most countable family of boxes covering $B$ has total volume at least $\operatorname{vol}(B)$ (e.g. by additivity of volume for finite unions and a limiting argument), so taking the infimum over all such covers yields $m(B)\ge \operatorname{vol}(B)$. Together with $m(B)\le \operatorname{vol}(B)$ this gives $m(B)=\operatorname{vol}(B)$, and therefore $\sum_{j\in J} m(B_j)=\sum_{j\in J}\operatorname{vol}(B_j)$.

The final displayed inequality follows by taking the infimum over all at most countable covers $(B_j)_{j\in J}$ of $\Omega$.
\end{proof}

