\begin{definition}
\label{def:7.4}
[Outer measure]
Let $n\in\mathbb{N}$ and let $\Omega\subseteq\mathbb{R}^n$. The \emph{outer measure} of $\Omega$ is the extended real number
\[
\label{eq:7.u14}
m^*(\Omega):=\inf\left\{\sum_{j\in J}\operatorname{vol}(B_j):\ (B_j)_{j\in J}\text{ is a cover of }\Omega,\ J\text{ is at most countable, and each }B_j\subseteq\mathbb{R}^n\text{ is a box}\right\},
\]
where $(B_j)_{j\in J}$ \emph{covers} $\Omega$ means $\Omega\subseteq\bigcup_{j\in J}B_j$, and $\operatorname{vol}(B_j)$ denotes the volume of the box $B_j$.
\end{definition}

\begin{lemma}
\label{lem:7.1}
[Properties of outer measure]
Let $m^*:\mathcal P(\mathbb R^n)\to[0,+\infty]$ be an outer measure, i.e. $m^*(\emptyset)=0$, $m^*(A)\le m^*(B)$ whenever $A\subseteq B$, and $m^*\bigl(\bigcup_{k=1}^\infty A_k\bigr)\le \sum_{k=1}^\infty m^*(A_k)$ for every sequence $(A_k)_{k\ge 1}$ of subsets of $\mathbb R^n$. Then the following hold:
\begin{enumerate}
\item[(v)] $m^*(\emptyset)=0$.
\item[(vi)] For every set $\Omega\subseteq\mathbb R^n$, one has $0\le m^*(\Omega)\le +\infty$.
\item[(vii)] If $A\subseteq B\subseteq \mathbb{R}^n$, then $m^*(A)\le m^*(B)$.
\item[(viii)] If $(A_j)_{j\in J}$ is a finite family of subsets of $\mathbb{R}^n$, then
\[
\label{eq:7.u15}
m^*\Bigl(\bigcup_{j\in J}A_j\Bigr)\le \sum_{j\in J} m^*(A_j).
\]
\item[(x)] If $(A_j)_{j\in J}$ is a countable family of subsets of $\mathbb{R}^n$, then
\[
\label{eq:7.u16}
m^*\Bigl(\bigcup_{j\in J}A_j\Bigr)\le \sum_{j\in J} m^*(A_j).
\]
\item[(xiii)] (Translation invariance) If, in addition, $m^*$ is translation invariant, namely $m^*(x+\Omega)=m^*(\Omega)$ for all $\Omega\subseteq\mathbb R^n$ and $x\in\mathbb R^n$, then this property holds.
\end{enumerate}
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:7.1}
Items (v), (vii), and (x) are exactly the defining properties of an outer measure.

For (vi), by definition $m^*(\Omega)\in[0,+\infty]$ for every $\Omega\subseteq\mathbb R^n$, hence $0\le m^*(\Omega)\le +\infty$.

For (viii), write the finite family as $A_1,\dots,A_N$. Define a sequence $(B_k)_{k\ge 1}$ by $B_k=A_k$ for $1\le k\le N$ and $B_k=\emptyset$ for $k>N$. Then
\[
\label{eq:7.u17}
m^*\Bigl(\bigcup_{j=1}^N A_j\Bigr)=m^*\Bigl(\bigcup_{k=1}^\infty B_k\Bigr)\le \sum_{k=1}^\infty m^*(B_k)=\sum_{j=1}^N m^*(A_j)+\sum_{k>N} m^*(\emptyset)=\sum_{j=1}^N m^*(A_j),
\]
using (v) in the last step.

Item (xiii) is immediate from the additional hypothesis of translation invariance.
\end{proof}

