\begin{proposition}
\label{prop:7.2}
[Outer measure of a closed box]
Let
\[
\label{eq:7.u18}
B=\prod_{i=1}^n[a_i,b_i]\subset\mathbb{R}^n
\]
be a closed box, where $a_i\le b_i$ for $1\le i\le n$. Let $m^*$ denote the outer measure on $\mathbb{R}^n$ defined as the infimum of $\sum_j \operatorname{vol}(U_j)$ over all countable covers of a set by open boxes $U_j$, where for an open box $\prod_{i=1}^n(\alpha_i,\beta_i)$ one sets $\operatorname{vol}\bigl(\prod_{i=1}^n(\alpha_i,\beta_i)\bigr)=\prod_{i=1}^n(\beta_i-\alpha_i)$. Then
\[
\label{eq:7.u19}
m^*(B)=\prod_{i=1}^n(b_i-a_i).
\]
\end{proposition}

\begin{theorem}
\label{thm:7.2}
Let $n\in\mathbb{N}$ and let $B\subset\mathbb{R}^n$ be an open box of the form
\[
\label{eq:7.u37}
B=\prod_{i=1}^n (a_i,b_i)=\{(x_1,\dots,x_n)\in\mathbb{R}^n: a_i<x_i<b_i\text{ for all }1\le i\le n\},
\]
where $a_i,b_i\in\mathbb{R}$ and $a_i\le b_i$ for all $i$. Then the outer measure of $B$ satisfies
\[
\label{eq:7.u38}
m^*(B)=\prod_{i=1}^n (b_i-a_i).
\]
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:7.2}
If $b_i=a_i$ for some $i$, then $B=\varnothing$, hence $m^*(B)=0$, and also $\prod_{i=1}^n(b_i-a_i)=0$.

Assume now that $b_i>a_i$ for all $i$. Fix $\varepsilon>0$ such that $b_i-\varepsilon>a_i+\varepsilon$ for all $i$, and define the closed boxes
\[
\label{eq:7.u39}
C_\varepsilon:=\prod_{i=1}^n [a_i+\varepsilon,b_i-\varepsilon],\qquad D:=\prod_{i=1}^n [a_i,b_i].
\]
Then $C_\varepsilon\subseteq B\subseteq D$. By monotonicity of outer measure,
\[
\label{eq:7.u40}
m^*(C_\varepsilon)\le m^*(B)\le m^*(D).
\]
For a closed box $\prod_{i=1}^n [\alpha_i,\beta_i]$, the outer measure equals its volume $\prod_{i=1}^n(\beta_i-\alpha_i)$. Applying this to $C_\varepsilon$ and $D$ gives
\[
\label{eq:7.u41}
\prod_{i=1}^n(b_i-a_i-2\varepsilon)=m^*(C_\varepsilon)\le m^*(B)\le m^*(D)=\prod_{i=1}^n(b_i-a_i).
\]
Letting $\varepsilon\downarrow 0$ yields $\prod_{i=1}^n(b_i-a_i-2\varepsilon)\to \prod_{i=1}^n(b_i-a_i)$, so the squeeze theorem implies $m^*(B)=\prod_{i=1}^n(b_i-a_i)$.
\end{proof}

