\begin{proposition}
\label{prop:7.4}
Let $m^*$ denote the one-dimensional Lebesgue outer measure on $\mathbb{R}$. If $A\subseteq\mathbb{R}$ is countable, then $m^*(A)=0$. In particular, $m^*(\mathbb{Q})=0$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.4}
If $A=\varnothing$, then $m^*(A)=0$.

Assume $A$ is nonempty and countable, so there exists an enumeration $A=\{a_1,a_2,\dots\}$. Let $\varepsilon>0$ be given. For each $n\in\mathbb{N}$, define the open interval
\[
\label{eq:7.u46}
I_n=\Bigl(a_n-\frac{\varepsilon}{2^{n+1}},\ a_n+\frac{\varepsilon}{2^{n+1}}\Bigr).
\]
Then $A\subseteq\bigcup_{n=1}^\infty I_n$, and the length of $I_n$ is $|I_n|=\varepsilon/2^n$. By the definition of outer measure as an infimum over countable interval covers,
\[
\label{eq:7.u47}
m^*(A)\le \sum_{n=1}^\infty |I_n|=\sum_{n=1}^\infty \frac{\varepsilon}{2^n}=\varepsilon.
\]
Since $\varepsilon>0$ was arbitrary, $m^*(A)=0$.

Taking $A=\mathbb{Q}$ gives $m^*(\mathbb{Q})=0$.
\end{proof}

