\begin{proposition}
\label{prop:7.5}
Let $m^*$ denote the one-dimensional outer measure on $\mathbb{R}$, defined by
\[
\label{eq:7.u48}
m^*(E)=\inf\Bigl\{\sum_{k=1}^\infty |I_k| : E\subseteq \bigcup_{k=1}^\infty I_k,\ I_k\text{ is an open interval in }\mathbb{R}\Bigr\},
\]
where $|I_k|$ denotes the length of $I_k$. Then
\[
\label{eq:7.u49}
m^*(\mathbb{R}\setminus\mathbb{Q})=+\infty.
\]
Moreover,
\[
\label{eq:7.u50}
m^*\bigl([0,1]\setminus\mathbb{Q}\bigr)=1.
\]
\end{proposition}

\begin{proposition}
\label{prop:7.6}
Let $m_2^*$ denote the two-dimensional Lebesgue outer measure on $\mathbb{R}^2$. Then
\[
\label{eq:7.u56}
m_2^*\bigl(\{(x,0):0\le x\le 1\}\bigr)=0.
\]
Consequently,
\[
\label{eq:7.u57}
m_2^*\bigl(\{(x,0):x\in\mathbb{R}\}\bigr)=0.
\]
\end{proposition}

\begin{proposition}
\label{prop:7.7}
Let $A\subseteq\mathbb{R}^n$ and $B\subseteq\mathbb{R}^m$. Then
\[
\label{eq:7.u62}
m_{n+m}^*(A\times B)\le m_n^*(A)\,m_m^*(B),
\]
where the product on the right-hand side is taken with the conventions: if $0<c\le +\infty$, then $c\cdot(+\infty)=(+\infty)\cdot c=+\infty$, and if $c=0$, then $0\cdot(+\infty)=(+\infty)\cdot 0=0$.
\end{proposition}

\begin{proposition}
\label{prop:7.8}
Let $(A_j)_{j\ge 1}$ be a sequence of Lebesgue measurable subsets of $\mathbb{R}^n$ such that $A_j\subseteq A_{j+1}$ for all $j$. Then
\[
\label{eq:7.u68}
m\Bigl(\bigcup_{j=1}^{\infty} A_j\Bigr)=\lim_{j\to\infty} m(A_j),
\]
where $m$ denotes Lebesgue measure.
\end{proposition}

\begin{proposition}
\label{prop:7.9}
Let $(A_j)_{j\ge 1}$ be a sequence of Lebesgue measurable subsets of $\mathbb{R}^n$ such that $A_{j+1}\subseteq A_j$ for all $j\ge 1$, and assume $m(A_1)<+\infty$. Then
\[
\label{eq:7.u74}
m\Bigl(\bigcap_{j=1}^{\infty} A_j\Bigr)=\lim_{j\to\infty} m(A_j).
\]
\end{proposition}

\begin{proposition}
\label{prop:7.10}
Let $n\in\mathbb{N}$ and let $q\in\mathbb{Z}$ with $q>1$. Define the open box
\[
\label{eq:7.u80}
(0,1/q)^n:=\{(x_1,\ldots,x_n)\in\mathbb{R}^n: 0<x_j<1/q\text{ for all }1\le j\le n\}
\]
and the closed box
\[
\label{eq:7.u81}
[0,1/q]^n:=\{(x_1,\ldots,x_n)\in\mathbb{R}^n: 0\le x_j\le 1/q\text{ for all }1\le j\le n\}.
\]
Then their Lebesgue measures satisfy
\[
\label{eq:7.u82}
m\bigl((0,1/q)^n\bigr)=m\bigl([0,1/q]^n\bigr)=q^{-n}.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.10}
The set difference $[0,1/q]^n\setminus (0,1/q)^n$ is contained in the union of the $2n$ coordinate ``faces''
\[
\label{eq:7.u83}
\bigcup_{j=1}^n\Bigl(\{x\in\mathbb{R}^n:x_j=0\}\cap[0,1/q]^n\Bigr)\ \cup\ \bigcup_{j=1}^n\Bigl(\{x\in\mathbb{R}^n:x_j=1/q\}\cap[0,1/q]^n\Bigr).
\]
Each face is contained in an affine hyperplane of the form $\{x\in\mathbb{R}^n:x_j=c\}$ and hence has Lebesgue measure $0$ in $\mathbb{R}^n$. By subadditivity, $m([0,1/q]^n\setminus (0,1/q)^n)=0$, and therefore
\[
\label{eq:7.u84}
m\bigl((0,1/q)^n\bigr)=m\bigl([0,1/q]^n\bigr).
\]
To compute the measure of the closed box, use the scaling property of Lebesgue measure: for any measurable set $E\subset\mathbb{R}^n$ and $a>0$, one has $m(aE)=a^n m(E)$. Applying this with $E=[0,1]^n$ and $a=1/q$ gives
\[
\label{eq:7.u85}
m\bigl([0,1/q]^n\bigr)=m\bigl((1/q)[0,1]^n\bigr)=(1/q)^n\, m([0,1]^n).
\]
Since $m([0,1]^n)=1$, it follows that $m([0,1/q]^n)=q^{-n}$, and hence also $m((0,1/q)^n)=q^{-n}$.
\end{proof}

