\begin{proposition}
\label{prop:7.11}
Let $B\subseteq\mathbb{R}^n$ be an axis-parallel box of the form
\[
\label{eq:7.u86}
B=\prod_{i=1}^n [a_i,b_i]\qquad(a_i,b_i\in\mathbb{R},\ a_i\le b_i).
\]
Then $B$ is Lebesgue measurable and
\[
\label{eq:7.u87}
m(B)=\operatorname{vol}(B)=\prod_{i=1}^n (b_i-a_i).
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.11}
Let $B=\prod_{i=1}^n [a_i,b_i]$ with $a_i\le b_i$. By Lemma 7.3(e), $B$ is Lebesgue measurable. If $b_i=a_i$ for some $i$, then $\operatorname{vol}(B)=0$. Also $B$ is contained in the hyperplane $\{x\in\mathbb{R}^n:x_i=a_i\}$, so $B$ has empty interior and can be covered by boxes of arbitrarily small total volume; hence $m(B)=0=\operatorname{vol}(B)$. Thus assume $b_i>a_i$ for all $i$.

Set $V:=\prod_{i=1}^n (b_i-a_i)$. For each $k\in\mathbb{N}$, subdivide each interval $[a_i,b_i]$ into $k$ equal subintervals of length $(b_i-a_i)/k$. This yields a partition of $B$ into $k^n$ pairwise disjoint axis-parallel subboxes $B_{\alpha}$ ($\alpha\in\{1,\dots,k\}^n$), each of volume
\[
\label{eq:7.u88}
\operatorname{vol}(B_{\alpha})=\prod_{i=1}^n \frac{b_i-a_i}{k}=\frac{V}{k^n}.
\]
By finite additivity of $m$ on disjoint boxes and the normalization $m(B_{\alpha})=\operatorname{vol}(B_{\alpha})$ on such elementary boxes, one has
\[
\label{eq:7.u89}
m(B)=\sum_{\alpha} m(B_{\alpha})=\sum_{\alpha} \operatorname{vol}(B_{\alpha})=k^n\cdot \frac{V}{k^n}=V.
\]
Therefore $m(B)=\operatorname{vol}(B)$.
\end{proof}

