\begin{proposition}
\label{prop:7.12}
[Failure of countable additivity]
There exists a countably infinite family $(A_j)_{j\in J}$ of pairwise disjoint subsets of $\mathbf{R}$ such that
\[
\label{eq:7.u90}
m^*\Bigl(\bigcup_{j\in J} A_j\Bigr) \neq \sum_{j\in J} m^*(A_j),
\]
where $m^*$ denotes Lebesgue outer measure on $\mathbf{R}$.
\end{proposition}

\begin{proposition}
\label{prop:7.13}
[Failure of finite additivity]
There exists a finite collection $(A_j)_{j\in J}$ of pairwise disjoint subsets of $\mathbb{R}$ such that
\[
m^*\Bigl(\bigcup_{j\in J} A_j\Bigr) \ne \sum_{j\in J} m^*(A_j),
\]
where $m^*$ denotes Lebesgue outer measure on $\mathbb{R}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.13}
Let $E$ and $X$ be the sets constructed in Proposition 7.12. By countable subadditivity and translation invariance,
\[
\label{eq:7.u91}
m^*(X) \le \sum_{q\in\mathbb{Q}\cap[-1,1]} m^*(q+E)=\sum_{q\in\mathbb{Q}\cap[-1,1]} m^*(E).
\]
Since $1\le m^*(X)\le 3$, we must have $m^*(E)\ne 0$. Choose $n\in\mathbb{N}$ such that $m^*(E)>1/n$, and let $J\subseteq\mathbb{Q}\cap[-1,1]$ be a finite set with $|J|=3n$. If $m^*$ were finitely additive, then
\[
\label{eq:7.u92}
m^*\Bigl(\bigcup_{q\in J} (q+E)\Bigr)=\sum_{q\in J} m^*(q+E)=|J|\,m^*(E)>3.
\]
But $\bigcup_{q\in J} (q+E)\subseteq X\subseteq[-1,2]$, so $m^*(\bigcup_{q\in J} (q+E))\le m^*([-1,2])=3$, a contradiction. Thus finite additivity fails.
\end{proof}

