\begin{definition}
\label{def:7.5}
[Lebesgue measurability]
Let $m^*$ denote the Lebesgue outer measure on $\mathbb{R}^n$. A set $E\subseteq\mathbb{R}^n$ is called \emph{Lebesgue measurable} (or \emph{measurable}) if for every set $A\subseteq\mathbb{R}^n$ one has
\[
\label{eq:7.u98}
m^*(A)=m^*(A\cap E)+m^*(A\setminus E).
\]
If $E$ is measurable, the \emph{Lebesgue measure} of $E$ is defined by $m(E):=m^*(E)$. If $E$ is not measurable, then $m(E)$ is left undefined.
\end{definition}

\begin{lemma}
\label{lem:7.2}
[Half-spaces are measurable]
Let $n\in\mathbb{N}$ and define the open half-space
\[
\label{eq:7.u99}
H:=\{(x_1,\ldots,x_n)\in\mathbb{R}^n : x_n>0\}.
\]
Then $H$ is Lebesgue measurable in $\mathbb{R}^n$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:7.2}
Define $f:\mathbb{R}^n\to\mathbb{R}$ by $f(x_1,\ldots,x_n)=x_n$. The map $f$ is continuous, hence Borel measurable. The set $(0,\infty)\subset\mathbb{R}$ is open, hence Borel. Therefore
\[
\label{eq:7.u100}
H=f^{-1}\bigl((0,\infty)\bigr)
\]
is a Borel set in $\mathbb{R}^n$. Every Borel set is Lebesgue measurable, so $H$ is Lebesgue measurable.
\end{proof}

