\begin{lemma}
\label{lem:7.3}
[Properties of measurable sets]
\begin{enumerate}
\item[(a)] If $E\subseteq \mathbb{R}^n$ is measurable, then $\mathbb{R}^n\setminus E$ is measurable.
\item[(b)] (Translation invariance) If $E\subseteq \mathbb{R}^n$ is measurable and $x\in\mathbb{R}^n$, then $x+E$ is measurable and $m(x+E)=m(E)$.
\item[(c)] If $E_1,E_2\subseteq \mathbb{R}^n$ are measurable, then $E_1\cap E_2$ and $E_1\cup E_2$ are measurable.
\item[(d)] (Boolean algebra property) If $E_1,\dots,E_N\subseteq \mathbb{R}^n$ are measurable, then $\bigcup_{j=1}^N E_j$ and $\bigcap_{j=1}^N E_j$ are measurable.
\item[(e)] Every open box and every closed box in $\mathbb{R}^n$ is measurable.
\item[(f)] If $E\subseteq \mathbb{R}^n$ satisfies $m^*(E)=0$, then $E$ is measurable.
\end{enumerate}
\end{lemma}

