\begin{lemma}
\label{lem:7.4}
[Finite additivity]
Let $m^*$ be an outer measure on a set $X$, and let $m$ be its restriction to the $m^*$-measurable sets. Let $(E_j)_{j\in J}$ be a finite family of pairwise disjoint $m^*$-measurable subsets of $X$. Then for every subset $A\subseteq X$,
\[
\label{eq:7.u101}
m^*\Bigl(A\cap\bigcup_{j\in J}E_j\Bigr)=\sum_{j\in J} m^*(A\cap E_j).
\]
In particular,
\[
\label{eq:7.u102}
m\Bigl(\bigcup_{j\in J}E_j\Bigr)=\sum_{j\in J} m(E_j).
\]
\end{lemma}

\begin{proposition}
\label{prop:7.14}
Let $(X,\mathcal{M},m)$ be a measure space. If $A,B\in\mathcal{M}$ and $A\subseteq B$, then $B\setminus A\in\mathcal{M}$ and
\[
\label{eq:7.u109}
m(B\setminus A)+m(A)=m(B).
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.14}
Since $A,B\in\mathcal{M}$ and $\mathcal{M}$ is a $\sigma$-algebra, the set difference $B\setminus A = B\cap A^c$ belongs to $\mathcal{M}$. Moreover, $A$ and $B\setminus A$ are disjoint and
\[
\label{eq:7.u110}
B = A\cup (B\setminus A).
\]
By additivity of the measure on disjoint measurable sets,
\[
\label{eq:7.u111}
m(B)=m\bigl(A\cup (B\setminus A)\bigr)=m(A)+m(B\setminus A),
\]
which is the desired identity.
\end{proof}

