\begin{lemma}
\label{lem:7.5}
(Countable additivity) Let $(X,\mathcal{M},m)$ be the measure space obtained by restricting the outer measure $m^*$ to the $m^*$-measurable sets. Let $(E_j)_{j\in J}$ be a countable family of pairwise disjoint sets in $\mathcal{M}$. Then $E:=\bigcup_{j\in J}E_j$ belongs to $\mathcal{M}$ and
\[
\label{eq:7.u112}
m(E)=\sum_{j\in J} m(E_j),
\]
where the sum is taken over any enumeration of $J$.
\end{lemma}

\begin{lemma}
\label{lem:7.6}
\label{lem:countable_disjoint_union_measurable}
Let $m^*$ be an outer measure on a set $X$, and let $m$ be the restriction of $m^*$ to the $m^*$-measurable sets. Let $\{E_j\}_{j\in J}$ be a countable family of pairwise disjoint $m^*$-measurable sets, and define $E=\bigcup_{j\in J} E_j$. Then $E$ is $m^*$-measurable and
\[
\label{eq:7.u124}
m(E)=\sum_{j\in J} m(E_j).
\]
\end{lemma}

\begin{lemma}
\label{lem:7.7}
($\sigma$-algebra property) Let $(\Omega,\mathcal{F})$ be a measurable space, and let $(\Omega_j)_{j\in J}$ be a countable collection of sets with $\Omega_j\in\mathcal{F}$ for all $j\in J$. Then $\bigcup_{j\in J}\Omega_j\in\mathcal{F}$ and $\bigcap_{j\in J}\Omega_j\in\mathcal{F}$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:7.7}
Since $J$ is countable, choose an enumeration $J=\{j_1,j_2,\dots\}$. By the defining property of a $\sigma$-algebra, $\bigcup_{n=1}^\infty \Omega_{j_n}\in\mathcal{F}$. Hence $\bigcup_{j\in J}\Omega_j\in\mathcal{F}$.

For the intersection, use De Morgan's law:
\[
\label{eq:7.u131}
\bigcap_{n=1}^\infty \Omega_{j_n}=\left(\bigcup_{n=1}^\infty \Omega_{j_n}^c\right)^c.
\]
Each $\Omega_{j_n}^c\in\mathcal{F}$ because $\mathcal{F}$ is closed under complements, so $\bigcup_{n=1}^\infty \Omega_{j_n}^c\in\mathcal{F}$ by countable unions, and then its complement also belongs to $\mathcal{F}$. Therefore $\bigcap_{j\in J}\Omega_j\in\mathcal{F}$.
\end{proof}

