\begin{lemma}
\label{lem:7.9}
[Borel property]
Every open subset of $\mathbb{R}^n$ and every closed subset of $\mathbb{R}^n$ is Lebesgue measurable.
\end{lemma}

\begin{proposition}
\label{prop:7.15}
Let $A\subseteq B\subseteq \mathbb{R}^n$. If $B$ is Lebesgue measurable and $m(B)=0$, then $A$ is Lebesgue measurable and $m(A)=0$.
\end{proposition}

\begin{proposition}
\label{prop:7.16}
Let $A\subseteq\mathbb{R}^2$ be defined by
\[
\label{eq:7.u141}
A := [0,1]^2\setminus \mathbb{Q}^2.
\]
Then $A$ is Lebesgue measurable, $m(A)=1$, and $\operatorname{int}(A)=\varnothing$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.16}
Since $\mathbb{Q}$ is countable, $\mathbb{Q}^2$ is countable. Every singleton $\{x\}\subset\mathbb{R}^2$ has Lebesgue measure $0$, hence by countable subadditivity $m(\mathbb{Q}^2)=0$. The set $[0,1]^2$ is Lebesgue measurable with $m([0,1]^2)=1$, and $\mathbb{Q}^2$ is measurable as a countable union of measurable singletons. Therefore $A=[0,1]^2\setminus\mathbb{Q}^2$ is Lebesgue measurable.

Moreover,
\[
\label{eq:7.u142}
1=m([0,1]^2)=m\bigl(A\cup([0,1]^2\cap\mathbb{Q}^2)\bigr)=m(A)+m([0,1]^2\cap\mathbb{Q}^2),
\]
where the last equality holds because $A$ and $[0,1]^2\cap\mathbb{Q}^2$ are disjoint measurable sets. Since $[0,1]^2\cap\mathbb{Q}^2\subseteq\mathbb{Q}^2$, it has measure $0$, hence $m(A)=1$.

To show $\operatorname{int}(A)=\varnothing$, let $x\in A$ and $r>0$. The open ball $B(x,r)$ contains a point $q\in\mathbb{Q}^2$ because $\mathbb{Q}^2$ is dense in $\mathbb{R}^2$. Also $B(x,r)$ contains a point $y\in\mathbb{R}^2\setminus\mathbb{Q}^2$ because $\mathbb{R}^2\setminus\mathbb{Q}^2$ is dense in $\mathbb{R}^2$. Choose $q$ so close to $x$ that $q\in [0,1]^2$ (possible since $[0,1]^2$ is closed and $x\in[0,1]^2$), then $q\in [0,1]^2\cap\mathbb{Q}^2\subseteq [0,1]^2\setminus A$, so $B(x,r)$ is not contained in $A$. Thus no point of $A$ is an interior point, and $\operatorname{int}(A)=\varnothing$.
\end{proof}

