\begin{definition}
\label{def:7.6}
[Measurable function]
Let $n,m\in\mathbb{N}$, let $\Omega\subseteq\mathbb{R}^n$ be a Lebesgue measurable set, and let $f:\Omega\to\mathbb{R}^m$ be a function. The function $f$ is called \emph{(Lebesgue) measurable} if for every open set $V\subseteq\mathbb{R}^m$, the preimage
\[
\label{eq:7.u143}
f^{-1}(V)=\{x\in\Omega: f(x)\in V\}
\]
is a Lebesgue measurable subset of $\Omega$.
\end{definition}

\begin{lemma}
\label{lem:7.10}
Let $\Omega\subseteq\mathbb{R}^n$ be a Lebesgue measurable set, and let $f:\Omega\to\mathbb{R}^m$ be continuous (with respect to the subspace topology on $\Omega$). Then $f$ is (Lebesgue) measurable, i.e. for every Borel set $B\subseteq\mathbb{R}^m$ the preimage $f^{-1}(B)$ is Lebesgue measurable in $\mathbb{R}^n$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:7.10}
Let $V\subseteq\mathbb{R}^m$ be open. By continuity of $f$ (relative to $\Omega$), the set $f^{-1}(V)$ is open in the subspace topology on $\Omega$. Hence there exists an open set $W\subseteq\mathbb{R}^n$ such that $f^{-1}(V)=W\cap\Omega$. Since $W$ is open, it is Borel and therefore Lebesgue measurable in $\mathbb{R}^n$. As $\Omega$ is Lebesgue measurable, the intersection $W\cap\Omega$ is Lebesgue measurable. Thus $f^{-1}(V)$ is Lebesgue measurable for every open $V\subseteq\mathbb{R}^m$.

Let $\mathcal{C}=\{B\subseteq\mathbb{R}^m: f^{-1}(B)\text{ is Lebesgue measurable in }\mathbb{R}^n\}$. Then $\mathcal{C}$ is a $\sigma$-algebra on $\mathbb{R}^m$ because preimages commute with complements and countable unions. Since all open sets $V$ belong to $\mathcal{C}$, the $\sigma$-algebra generated by the open sets, namely the Borel $\sigma$-algebra $\mathcal{B}(\mathbb{R}^m)$, is contained in $\mathcal{C}$. Therefore $f^{-1}(B)$ is Lebesgue measurable for every Borel set $B\subseteq\mathbb{R}^m$, so $f$ is measurable.
\end{proof}

