\begin{lemma}
\label{lem:7.11}
Let $\Omega$ be a measurable subset of $\mathbb{R}^n$, and let $f: \Omega \to \mathbb{R}^m$ be a function. Then $f$ is measurable if and only if $f^{-1}(B)$ is measurable for every open box $B\subseteq\mathbb{R}^m$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:7.11}
Assume first that $f$ is measurable. By definition, for every open set $U\subseteq\mathbb{R}^m$, the preimage $f^{-1}(U)$ is measurable in $\Omega$. In particular, this holds for every open box $B$.

Conversely, assume that $f^{-1}(B)$ is measurable for every open box $B\subseteq\mathbb{R}^m$. Let $U\subseteq\mathbb{R}^m$ be open. For each $x\in U$, choose $r_x>0$ such that the open Euclidean ball $B(x,r_x)\subseteq U$. Choose $q_x\in\mathbb{Q}^m$ and $\rho_x\in\mathbb{Q}$ with $0<\rho_x<r_x$ and $\lVert q_x-x\rVert<r_x-\rho_x$, which implies $B(q_x,\rho_x)\subseteq B(x,r_x)\subseteq U$. For each such pair $(q,\rho)$ define the open box
\[
\label{eq:7.u144}
C(q,\rho)=\prod_{j=1}^m (q_j-\rho/\sqrt m,\, q_j+\rho/\sqrt m).
\]
Then $C(q,\rho)\subseteq B(q,\rho)\subseteq U$. Therefore
\[
\label{eq:7.u145}
U=\bigcup_{(q,\rho)\in S} C(q,\rho),
\]
where $S\subseteq\mathbb{Q}^m\times\mathbb{Q}_{>0}$ is the (countable) set of pairs with $C(q,\rho)\subseteq U$. Hence
\[
\label{eq:7.u146}
f^{-1}(U)=\bigcup_{(q,\rho)\in S} f^{-1}(C(q,\rho)).
\]
Each $C(q,\rho)$ is an open box, so $f^{-1}(C(q,\rho))$ is measurable by hypothesis, and the countable union is measurable. Thus $f^{-1}(U)$ is measurable for every open $U$, so $f$ is measurable.
\end{proof}

