\begin{theorem}
\label{thm:7.3}
Let \(\Omega\subseteq\mathbb{R}^n\) be a measurable set. Let \(f:\Omega\to\mathbb{R}^m\) and write \(f=(f_1,\dots,f_m)\), where \(f_j:\Omega\to\mathbb{R}\) denotes the \(j\)th coordinate function. Then \(f\) is measurable (with respect to the Lebesgue \(\sigma\)-algebras on \(\Omega\) and \(\mathbb{R}^m\)) if and only if each \(f_j\) is measurable.
\end{theorem}

\begin{lemma}
\label{lem:7.12}
Let $\Omega\subseteq\mathbb{R}^n$ be a measurable set, let $W\subseteq\mathbb{R}^m$ be open, and let $f:\Omega\to W$ be measurable. If $g:W\to\mathbb{R}^p$ is continuous, then the composition $g\circ f:\Omega\to\mathbb{R}^p$ is measurable.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:7.12}
Since $g$ is continuous, for every open set $U\subseteq\mathbb{R}^p$ the preimage $g^{-1}(U)$ is open in $W$, hence there exists an open set $V\subseteq\mathbb{R}^m$ such that $g^{-1}(U)=W\cap V$. Then
\[
\label{eq:7.u151}
(g\circ f)^{-1}(U)=f^{-1}\bigl(g^{-1}(U)\bigr)=f^{-1}(W\cap V)=f^{-1}(V).
\]
Because $f$ is measurable and $V$ is open in $\mathbb{R}^m$, the set $f^{-1}(V)$ is measurable in $\Omega$. Therefore $(g\circ f)^{-1}(U)$ is measurable for every open $U\subseteq\mathbb{R}^p$, which implies that $g\circ f$ is measurable.
\end{proof}

