\begin{theorem}
\label{thm:7.4}
Let $\Omega\subseteq\mathbb{R}^n$ be measurable, and let $f:\Omega\to\mathbb{R}$ be measurable. Then the functions $|f|$, $\max(f,0)$, and $\min(f,0)$ defined by
\[
\label{eq:7.u152}
|f|(x)=|f(x)|,\qquad \max(f,0)(x)=\max\{f(x),0\},\qquad \min(f,0)(x)=\min\{f(x),0\},
\]
are measurable on $\Omega$.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:7.4}
The function $\phi:\mathbb{R}\to\mathbb{R}$ given by $\phi(t)=|t|$ is continuous, hence Borel measurable. Since $f$ is measurable on $\Omega$, the composition $\phi\circ f=|f|$ is measurable on $\Omega$.

Similarly, the functions $\psi(t)=\max\{t,0\}$ and $\eta(t)=\min\{t,0\}$ are continuous on $\mathbb{R}$, hence Borel measurable. Therefore $\psi\circ f=\max(f,0)$ and $\eta\circ f=\min(f,0)$ are measurable on $\Omega$.
\end{proof}

