\begin{theorem}
\label{thm:7.5}
Let $\Omega\subseteq\mathbb{R}^n$ be measurable, and let $f,g:\Omega\to\mathbb{R}$ be measurable functions. Then the functions $f+g$, $f-g$, $fg$, $\max(f,g)$, and $\min(f,g)$ are measurable on $\Omega$. If, in addition, $g(x)\neq 0$ for all $x\in\Omega$, then $f/g$ is measurable on $\Omega$.
\end{theorem}

\begin{lemma}
\label{lem:7.13}
Let \(\Omega\subseteq\mathbb{R}^n\) be a measurable set (with respect to the Lebesgue \(\sigma\)-algebra), and let \(f:\Omega\to\mathbb{R}\) be a function. Then \(f\) is measurable if and only if \(f^{-1}((a,\infty))\) is measurable in \(\Omega\) for every \(a\in\mathbb{R}\).
\end{lemma}

\begin{definition}
\label{def:7.7}
[Measurable functions in the extended reals]
Let \(\Omega\subset\mathbb{R}^n\) be a measurable set and let \(\mathbb{R}^*:=\mathbb{R}\cup\{+\infty,-\infty\}\). A function \(f:\Omega\to\mathbb{R}^*\) is called \emph{measurable} if, for every \(a\in\mathbb{R}\), the set
\[
\label{eq:7.u160}
\{x\in\Omega: f(x)\in(a,+\infty]\}=f^{-1}((a,+\infty])
\]
is measurable (as a subset of \(\Omega\), equivalently of \(\mathbb{R}^n\)).
\end{definition}

\begin{lemma}
\label{lem:7.14}
[Limits of measurable functions are measurable]
Let $\Omega\subseteq\mathbb{R}^n$ be a measurable set (with respect to the Lebesgue $\sigma$-algebra), and let $(f_n)_{n\ge 1}$ be measurable functions $f_n:\Omega\to\mathbb{R}^*:=\mathbb{R}\cup\{\pm\infty\}$. Define, for $x\in\Omega$,
\[
\label{eq:7.u161}
\Big(\sup_{n\ge 1} f_n\Big)(x):=\sup_{n\ge 1} f_n(x),\quad
\Big(\inf_{n\ge 1} f_n\Big)(x):=\inf_{n\ge 1} f_n(x),
\]
\[
\label{eq:7.u162}
\big(\limsup_{n\to\infty} f_n\big)(x):=\lim_{N\to\infty}\sup_{n\ge N} f_n(x),\quad
\big(\liminf_{n\to\infty} f_n\big)(x):=\lim_{N\to\infty}\inf_{n\ge N} f_n(x).
\]
Then $\sup_{n\ge 1} f_n$, $\inf_{n\ge 1} f_n$, $\limsup_{n\to\infty} f_n$, and $\liminf_{n\to\infty} f_n$ are measurable functions $\Omega\to\mathbb{R}^*$. In particular, if $f_n(x)\to f(x)$ for all $x\in\Omega$ for some $f:\Omega\to\mathbb{R}^*$, then $f$ is measurable.
\end{lemma}

\begin{proposition}
\label{prop:7.17}
Let $f:\mathbb{R}^n\to\mathbb{R}$ be Lebesgue measurable. Let $g:\mathbb{R}^n\to\mathbb{R}$ and suppose there exists a Lebesgue null set $A\subseteq\mathbb{R}^n$ such that $f(x)=g(x)$ for all $x\in\mathbb{R}^n\setminus A$. Then $g$ is Lebesgue measurable.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:7.17}
Fix $\alpha\in\mathbb{R}$ and set
\[
\label{eq:7.u166}
E_f(\alpha)=\{x\in\mathbb{R}^n: f(x)>\alpha\},\qquad E_g(\alpha)=\{x\in\mathbb{R}^n: g(x)>\alpha\}.
\]
For $x\in\mathbb{R}^n\setminus A$ the equality $f(x)=g(x)$ implies $x\in E_f(\alpha)$ if and only if $x\in E_g(\alpha)$. Hence
\[
\label{eq:7.u167}
E_g(\alpha)\,\Delta\,E_f(\alpha)\subseteq A,
\]
where $\Delta$ denotes symmetric difference. Therefore there exists a set $N_\alpha\subseteq A$ such that
\[
\label{eq:7.u168}
E_g(\alpha)=E_f(\alpha)\cup N_\alpha.
\]
Since $f$ is Lebesgue measurable, $E_f(\alpha)$ is Lebesgue measurable. Since $A$ is Lebesgue null, every subset of $A$ is Lebesgue measurable, so $N_\alpha$ is Lebesgue measurable. Consequently $E_g(\alpha)$ is Lebesgue measurable.

Because $\alpha\in\mathbb{R}$ was arbitrary, the superlevel sets $\{x: g(x)>\alpha\}$ are Lebesgue measurable for all $\alpha$, which implies that $g$ is Lebesgue measurable.
\end{proof}
